private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If the string is null, only return true if the prefix is also null
    if (str == null) {
        return prefix == null;
    }
    // If the prefix is null, the string always starts with a null prefix
    if (prefix == null) {
        return true;
    }

    final int prefixLen = prefix.length();
    // If the prefix is longer than the string, it cannot match
    if (prefixLen > str.length()) {
        return false;
    }

    if (ignoreCase) {
        // regionMatches with ignoreCase set to true performs case-insensitive comparison
        return str.regionMatches(true, 0, prefix, 0, prefixLen);
    } else {
        return str.startsWith(prefix);
    }
}

