        if (value instanceof String) {
            String s = (String) value;
            if (s.length() == 1) {
                return s.charAt(0);
            } else {
                throw new Exception("Cannot convert String with length != 1 to Character");
            }
        }
        throw new Exception("Unsupported value type for Character conversion: " + value.getClass());
    }
    throw new Exception("Unsupported target type: " + type);
