private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> newParent = node.left;
    if (newParent == null) {
        return node; // nothing to rotate
    }

    // Reattach newParent's right subtree as node's left subtree
    node.left = newParent.right;
    if (newParent.right != null) {
        newParent.right.parent = node;
    }

    // Update parent references
    newParent.parent = node.parent;
    if (node.parent == null) {
        // node was the root; caller should update the tree root to newParent
    } else if (node.parent.right == node) {
        node.parent.right = newParent;
    } else {
        node.parent.left = newParent;
    }

    // Make node a child of newParent
    newParent.right = node;
    node.parent = newParent;

    return newParent;
}

