    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> pivot = node.left;
    // detach pivot's right subtree
    node.left = pivot.right;
    if (pivot.right != null) {
        pivot.right.parent = node;
    }
    // pivot becomes parent
    pivot.right = node;
    // update parent links
