private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    ListNodeImpl<E> prev = node.previous;
    ListNodeImpl<E> next = node.next;

    if (prev == null) {
        // node is the first element
        head = next;
    } else {
        prev.next = next;
    }

    if (next == null) {
        // node is the last element
        tail = prev;
    } else {
        next.previous = prev;
    }

    // clear references in the removed node
    node.next = null;
    node.previous = null;

    size--;
    return true;
}

