private void moveAllListNodes(DoublyLinkedList<E> list) {
    // If the source and destination are the same list or the source is empty, nothing to do.
    if (list == this || list.size == 0) {
        return;
    }

    // Link the two lists together.
    if (this.size == 0) {
        // Destination list is empty: just adopt the nodes from the source list.
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Destination list is non‑empty: attach the source list after the current tail.
        this.tail.next = list.head;      // assuming ListNodeImpl<E> has `next`
        list.head.prev = this.tail;      // assuming ListNodeImpl<E> has `prev`
        this.tail = list.tail;
    }

    // Update size information
    this.size += list.size;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

