private int computeBinaryLog(int n){
    // Handles non-positive input by returning 0
    if (n <= 0) {
        return 0;
    }
    // The number of bits required to represent n is
    // floor(log2(n)) + 1, which equals 32 minus the
    // count of leading zero bits in the 32‑bit integer.
    return 32 - Integer.numberOfLeadingZeros(n);
}

