protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return new GraphWalk<>(graph, null, null, new ArrayList<>(), new ArrayList<>());
    }
    // Determine whether the graph is directed
    final boolean directed = graph.getType().isDirected();
    // Keep a mutable copy of the remaining edges
    Set<E> remaining = new HashSet<>(tour);
    // Pick an arbitrary starting edge
    Iterator<E> it = remaining.iterator();
    E first = it.next();
    it.remove();
    // Initialize vertex and edge lists
    List<E> edges = new ArrayList<>();
    List<V> vertices = new ArrayList<>();
    V src = graph.getEdgeSource(first);
    V tgt = graph.getEdgeTarget(first);
    edges.add(first);
    vertices.add(src);
    vertices.add(tgt);
    V current = tgt;
    // Iterate until all edges are consumed
    while (!remaining.isEmpty()){
        boolean found = false;
        E nextEdge = null;
        V nextVertex = null;
        for (E e : remaining){
            V eSrc = graph.getEdgeSource(e);
            V eTgt = graph.getEdgeTarget(e);
            if (directed){
                if (eSrc.equals(current)){
                    nextEdge = e;
                    nextVertex = eTgt;
                    found = true;
                    break;
                }
            } else {
                if (eSrc.equals(current)){
                    nextEdge = e;
                    nextVertex = eTgt;
                    found = true;
                    break;
                } else if (eTgt.equals(current)){
                    nextEdge = e;
                    nextVertex = eSrc;
                    found = true;
                    break;
                }
            }
        }
        if (!found){
            throw new IllegalArgumentException("The provided set of edges does not form a continuous tour.");
        }
        edges.add(nextEdge);
        remaining.remove(nextEdge);
        // Only add the vertex if it's not a repetition of the start in a cycle
        if (!nextVertex.equals(vertices.get(0)) || !remaining.isEmpty()){
            vertices.add(nextVertex);
        }
        current = nextVertex;
    }
    return new GraphWalk<>(graph, vertices.get(0), current, edges, vertices);
}

