private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            bounds.add(-1);
        } else if (key instanceof Integer) {
            // For integer keys, we consider the "upper bound" as the next integer value.
            bounds.add(((Integer) key) + 1);
