private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // A null or empty set is considered a clique
    if (vertices == null || vertices.size() <= 1) {
        return true;
    }
    // Iterate over all unordered pairs of vertices
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            // If there is no edge between v1 and v2, it's not a clique
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

