public final MatchResult match(CharSequence uri) {
    if (uri == null) {
        return null;
    }
    // Split the URI and the template into segments, ignoring leading slashes.
    String[] uriParts = uri.toString().split("/");
    String[] templateParts = this.template.split("/");

    // If the number of segments differs, this URI cannot match the template.
    if (uriParts.length != templateParts.length) {
        return null;
    }

    java.util.Map<String, String> extracted = new java.util.HashMap<>();

    for (int i = 0; i < uriParts.length; i++) {
        String tmplSeg = templateParts[i];
        String uriSeg = uriParts[i];

        // A template segment in the form "{name}" indicates a variable capture.
        if (tmplSeg.startsWith("{") && tmplSeg.endsWith("}")) {
            String varName = tmplSeg.substring(1, tmplSeg.length() - 1);
            extracted.put(varName, uriSeg);
        } else {
            // Literal segments must exactly match.
            if (!tmplSeg.equals(uriSeg)) {
                return null;
            }
        }
    }

    // Assume MatchResult has a constructor that takes a Map of variables.
    return new MatchResult(extracted);
}

