private Class<?> findClass(final String className) throws ClassNotFoundException {
    if (className == null) {
        throw new IllegalArgumentException("className may not be null");
    }

    Class<?> result = null;
    ClassLoader contextLoader = Thread.currentThread().getContextClassLoader();
    try {
        result = Class.forName(className, true, contextLoader);
    } catch (ClassNotFoundException e) {
        // Try fallback with the class's own class loader
        ClassLoader ownLoader = this.getClass().getClassLoader();
        if (ownLoader != null && ownLoader != contextLoader) {
            result = Class.forName(className, true, ownLoader);
        } else {
            // rethrow original exception
            throw e;
        }
    }

    if (result == null) {
        throw new ClassNotFoundException("Class " + className + " could not be found");
    }

    return result;
}

