    if (table == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }

    // Clear current selection and select the specified row
    table.clearSelection();
    table.setRowSelectionInterval(row, row);

    // Request focus on the table
    table.requestFocusInWindow();

    // Make the selected row visible by scrolling the viewport
    Rectangle cellRect = table.getCellRect(row, 0, true);
    if (cellRect != null) {
        table.scrollRectToVisible(cellRect);
        if (pane != null) {
            // Ensure the viewport position is updated if the pane is provided
            if (pane.getViewport() != null) {
                pane.getViewport().setViewPosition(new java.awt.Point(cellRect.x, cellRect.y));
            }
        }
    }

    // Delay repaint to allow the table to paint the newly selected row properly
    javax.swing.SwingUtilities.invokeLater(() -> {
        javax.swing.Timer repaintTimer = new javax.swing.Timer(40, e -> {
            table.repaint();
        });
        repaintTimer.setRepeats(false);
        repaintTimer.start();
    });
}

