public synchronized void send(final String message) {
    if (message == null || clientWriters.isEmpty()) {
        return;
    }
    Iterator<BufferedWriter> it = clientWriters.iterator();
    while (it.hasNext()) {
        BufferedWriter writer = it.next();
        try {
            writer.write(message);
            writer.write("\r\n");
            writer.flush();
        } catch (IOException e) {
            // Unable to send to this client; clean up
            try {
                writer.close();
            } catch (IOException closeEx) {
                // ignore secondary exception
            }
            it.remove();
        }
    }
}

