public void abbreviate(final int nameStart, final StringBuffer buf){
    // Ensure the buffer contains enough characters to abbreviate
    if (buf == null || nameStart >= buf.length()) {
        return;
    }
    // Extract the portion of the buffer that needs abbreviating
    String sub = buf.substring(nameStart);
    // Build the abbreviation: keep first character of each component separated by '.' or '/'
    StringBuilder abbrev = new StringBuilder();
    boolean startOfComponent = true;
    for (int i = 0; i < sub.length(); i++) {
        char ch = sub.charAt(i);
        if (ch == '.' || ch == '/') {
            // Preserve the separator
            abbrev.append(ch);
            startOfComponent = true;  // next component starts after separator
        } else if (startOfComponent) {
            // Append the first character of the component
            abbrev.append(ch);
            startOfComponent = false;
        }
        // All subsequent characters in the component are skipped
    }
    // Replace the original portion of the buffer with the abbreviation
    buf.replace(nameStart, buf.length(), abbrev.toString());
}

