public boolean isExpired(long timestamp, long expiredThreshold) {
    // timestamp represents the last update time of the metric (in milliseconds)
    // expiredThreshold represents the allowed duration between the last update
    // time and the point at which the metric should be removed from cache.
    // Compare the current system time against the sum of the timestamp and threshold.
    long currentTime = System.currentTimeMillis();
    return currentTime - timestamp > expiredThreshold;
}

