    // The implementation of fetchCurrentMapping is environment‑specific
    // and should return a Mappings instance containing the latest
    // mapping for the index.
    Mappings currentMappings = fetchCurrentMapping(tableName);
    if (currentMappings == null) {
        // If we cannot obtain the current mapping, return an empty mapping
        return new Mappings();
    }

