    Map<String, Object> currentProps = (Map<String, Object>) currentMappings.getSource().get("properties");
    Map<String, Object> historyProps = (Map<String, Object>) historyMappings.getSource().get("properties");

    if (currentProps == null || historyProps == null) {
        return new Mappings();
    }

    // Build a map of fields that exist in the current mapping but not in the history mapping
    Map<String, Object> diffProps = new HashMap<>();
    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String field = entry.getKey();
        if (!historyProps.containsKey(field)) {
            diffProps.put(field, entry.getValue());
        }
    }

    if (diffProps.isEmpty()) {
        // No new fields to add
        return new Mappings();
    }

    // Construct the diff mapping
    Map<String, Object> newSource = new HashMap<>();
    newSource.put("properties", diffProps);

