    String dist = System.getProperty("dist.path");
    if(dist == null){
        dist = System.getenv("DIST_PATH");
    }
    if(dist == null){
        dist = "dist";
    }
    File distDir = new File(dist);
    // Create directory if it doesn't exist
    if(!distDir.exists()){
        if(!distDir.mkdirs()){
            throw new IllegalStateException("Failed to create distribution directory: " + distDir.getAbsolutePath());
        }
    }
    if(!distDir.isDirectory()){
        throw new IllegalStateException("Distribution path must be a directory: " + distDir.getAbsolutePath());
    }
    if(!distDir.canWrite()){
        throw new IllegalStateException("No write permission for distribution directory: " + distDir.getAbsolutePath());
    }
    // Store absolute path
    this.distPath = distDir.getAbsolutePath();
    // Load configuration file if present
    File configFile = new File(distDir, "config.properties");
    if(configFile.exists()){
        try (InputStream in = new FileInputStream(configFile)) {
            Properties props = new Properties();
            props.load(in);
            this.config = props;
        } catch (IOException e) {
            throw new IllegalStateException("Failed to load configuration from " + configFile.getAbsolutePath(), e);
        }
    } else {
        // no config file; initialize empty properties
        this.config = new Properties();
    }
}

