public boolean equals(final byte[] data,int offset,final int len){
    // Null checks for external array
    if (data == null) {
        return false;
    }
    // Ensure internal array is not null
    byte[] internal = this.array;
    if (internal == null) {
        return false;
    }
    int internalLen = internal.length;
    // Default len to full length if negative
    int compareLen = len < 0? internalLen : len;
    // Length must match
    if (compareLen != internalLen) {
        return false;
    }
    // Offset bounds check
    if (offset < 0 || offset + compareLen > data.length) {
        return false;
    }
    // Element-wise comparison
    for (int i = 0; i < compareLen; i++) {
        if (internal[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

