public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    int start = index;
    int end = Math.min(str.length(), index + len);
    int size = 0;
    for (int i = start; i < end; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {                     // 1-byte
            size += 1;
        } else if (ch < 0x800) {              // 2-byte
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                int codePoint = Character.codePointAt(str, i);
                if (codePoint <= 0xFFFF) {    // should not happen for surrogate pair
                    size += 3;
                } else {                     // 4-byte
                    size += 4;
                }
                i++; // skip low surrogate
            } else {                           // unpaired high surrogate
                size += 3;                      // replacement character U+FFFD
            }
        } else if (Character.isLowSurrogate(ch)) {
            size += 3;                          // unpaired low surrogate
        } else {                                 // 3-byte
            size += 3;
        }
    }
    return size;
}

