public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    // Prepare a UTF‑8 encoder
    final java.nio.charset.CharsetEncoder encoder = java.nio.charset.StandardCharsets.UTF_8.newEncoder();
    java.nio.CharBuffer cb = java.nio.CharBuffer.wrap(str);
    // Allocate a buffer large enough for the worst‑case byte count
    int maxBytes = (int) (encoder.maxBytesPerChar() * str.length());
    java.nio.ByteBuffer bb = java.nio.ByteBuffer.allocate(maxBytes);
    try {
        encoder.encode(cb, bb, true);
        encoder.flush(bb);
    } catch (java.nio.charset.CharacterCodingException e) {
        throw new RuntimeException("Failed to encode string to UTF‑8", e);
    }
    bb.flip(); // ready for reading
    // Write the encoded bytes to the provided LinkedBuffer via the WriteSession
    session.write(bb, lb);
    return lb;
}

