    // The tag encodes both the field number and the wire type.
    // For packed repeated primitives the wire type is LENGTH_DELIMITED (2).
    // If this field is repeated and the wire type matches, we record that we are
    // currently reading a packed field.  The length of the packed data is
    // read by the caller; here we only update the state flag.
    final int WIRETYPE_LENGTH_DELIMITED = 2;
    // Extract the wire type from the tag (lowest 3 bits).
    int wireType = this.currentTag & 0x7;
    // Determine whether the current field is a repeated field.
    // The field descriptor is assumed to be available as this.currentField.
    boolean isRepeated = this.currentField.isRepeated();
    // Update internal state accordingly.
    if (wireType == WIRETYPE_LENGTH_DELIMITED && isRepeated) {
        // Set flag indicating that packed fields are being read.
        this.readingPacked = true;
    } else {
        this.readingPacked = false;
    }
}

